#!/bin/bash
set -euo pipefail
# Backup for the EventFlow Docker stack (runs on the VPS as the deploy user,
# usually from cron). Dumps the MariaDB database (streamed, gzip) and tars
# the media directory into ${STATE_DIR}/backups. Retention: 14 days.
# Never prints credentials.

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=lib.sh
source "${SCRIPT_DIR}/../lib.sh"

BACKUP_DIR="${BACKUP_DIR:-${STATE_DIR}/backups}"
RETENTION_DAYS="${RETENTION_DAYS:-14}"
TS="$(date +%Y%m%d-%H%M%S)"

mkdir -p "$BACKUP_DIR"

# Load DB_* (KEY=VAL file, generated by bootstrap — values never echoed).
set -a
# shellcheck disable=SC1090
. "$ENV_FILE"
set +a
: "${DB_NAME:=eventflow}"
: "${DB_USER:=eventflow}"
[ -n "${DB_PASSWORD:-}" ] || fail "DB_PASSWORD missing from ${ENV_FILE}"

log "dumping database ${DB_NAME} …"
DB_DUMP="${BACKUP_DIR}/eventflow-db-${TS}.sql.gz"
# MYSQL_PWD keeps the password out of the process argv.
compose exec -T -e "MYSQL_PWD=${DB_PASSWORD}" mariadb \
    mariadb-dump --single-transaction --quick --routines --triggers \
    -u"${DB_USER}" "${DB_NAME}" | gzip > "$DB_DUMP"
gzip -t "$DB_DUMP" || { rm -f "$DB_DUMP"; fail "database dump failed gzip integrity check"; }

log "archiving media …"
MEDIA_DIR="${EVENTFLOW_MEDIA_DIR:-/srv/baseify/eventflow/media}"
[ -d "$MEDIA_DIR" ] || fail "media directory missing: ${MEDIA_DIR}"
MEDIA_TAR="${BACKUP_DIR}/eventflow-media-${TS}.tar.gz"
tar -czf "$MEDIA_TAR" -C "$(dirname "$MEDIA_DIR")" "$(basename "$MEDIA_DIR")"
gzip -t "$MEDIA_TAR" || { rm -f "$MEDIA_TAR"; fail "media archive failed gzip integrity check"; }

# Retention (only our own file patterns).
find "$BACKUP_DIR" -name 'eventflow-db-*.sql.gz'  -mtime +"${RETENTION_DAYS}" -delete
find "$BACKUP_DIR" -name 'eventflow-media-*.tar.gz' -mtime +"${RETENTION_DAYS}" -delete

log "backup OK: $(du -h "$DB_DUMP" | cut -f1) db, $(du -h "$MEDIA_TAR" | cut -f1) media → ${BACKUP_DIR}"
